# touch SQLite/Redis/MEGA and therefore cannot become another correctness dependency.
R52_FORENSIC_BUTTON_LOG = str(os.getenv('R52_FORENSIC_BUTTON_LOG', '1') or '1').strip().lower() not in {'0','false','no','off'}
R52_FORENSIC_HEARTBEAT_SECONDS = max(1.0, min(10.0, float(os.getenv('R52_FORENSIC_HEARTBEAT_SECONDS', '2') or '2')))
_R52_LAST_CALLBACK_MONO = 0.0
_R52_DIAG_LOCK = threading.RLock()
_R52_SECRET_FIELD_WORDS = ('token','secret','password','authorization','cookie','session','credential','private_key')

def _r52_safe_diag_value(name, value, limit=700):
    try:
        low = str(name or '').casefold()
        if any(word in low for word in _R52_SECRET_FIELD_WORDS):
            return '<redacted>'
        if isinstance(value, float):
            return f'{value:.3f}'
        if isinstance(value, (dict,list,tuple,set)):
            value = json.dumps(value, ensure_ascii=False, separators=(',',':'), default=str)
        text = str(value if value is not None else '')
        text = text.replace('\n','\\n').replace('\r','\\r')
        return text[:max(40,int(limit))]
    except Exception:
        return '<unprintable>'

def r52_diag(event: str, **fields):
    if not R52_FORENSIC_BUTTON_LOG:
        return
    try:
        base = [f'R52DIAG event={str(event or "?")[:80]}', f'mono={time.monotonic():.3f}',
                f'thread={threading.current_thread().name}', f'tid={threading.get_ident()}']
        for key, value in fields.items():
            base.append(f'{str(key)[:64]}={_r52_safe_diag_value(key,value)}')
        line = ' '.join(base)
        fn = globals().get('log_info')
        if callable(fn): fn(line)
        else: logging.info(line)
        ring = globals().get('r26_diag_trace_line')
        if callable(ring): ring(line)
    except Exception:
        pass

def r52_note_callback_activity():
    global _R52_LAST_CALLBACK_MONO
    try: _R52_LAST_CALLBACK_MONO = time.monotonic()
    except Exception: pass

def _r52_pool_key_interesting(key) -> bool:
    if str(os.getenv('R52_FORENSIC_POOL_ALL','0') or '0').strip().lower() in {'1','true','yes','on'}:
        return True
    low = str(key or '').casefold()
    return any(x in low for x in ('callback','fast-window','fast-pair','finance-ui','window-render','r22-','r25-','r48-','start:','restore'))

class KeyedTaskPool:

    def __init__(self, name: str, workers: int=4, max_pending: int=1000):
        self.name = str(name)
        self.workers = max(1, int(workers))
        self.max_pending = max(10, int(max_pending))
        self._ready = queue.Queue()
        self._lock = threading.RLock()
        self._by_key = defaultdict(deque)
        self._active_keys = set()
        self._pending = 0
        self._active_workers = 0
        self._submitted = 0
        self._completed = 0
        self._failed = 0
        self._rejected = 0
        self._max_wait = 0.0
        self._last_error = ''
        self._running = {}
        for idx in range(self.workers):
            t = threading.Thread(target=self._worker, name=f'{self.name}-{idx + 1}', daemon=True)
            t.start()

    def submit(self, key, func, *args, **kwargs) -> bool:
        key = str(key)
        with self._lock:
            if self._pending >= self.max_pending:
                self._rejected += 1
                return False
            self._by_key[key].append((func, args, kwargs, time.time()))
            self._pending += 1
            self._submitted += 1
            if key not in self._active_keys:
                self._active_keys.add(key)
                self._ready.put(key)
            _r52_snap = (self._pending, self._active_workers, len(self._active_keys), len(self._by_key.get(key) or ()))
        if _r52_pool_key_interesting(key):
            r52_diag('POOL_SUBMIT', pool=self.name, key=key, pending=_r52_snap[0], active=_r52_snap[1], keys=_r52_snap[2], key_queued=_r52_snap[3], func=getattr(func,'__name__',type(func).__name__))
        return True

    def submit_unique(self, key, func, *args, **kwargs) -> bool:
        """Submit only when this logical key has no active/queued task.

        Used for heavy interactive file exports: repeated button presses must coalesce
        instead of building a long queue of the same ZIP/XLSX/journal job. Existing
        submit() semantics remain unchanged for finance/forward/business queues.
        """
        key = str(key)
        with self._lock:
            if key in self._active_keys or bool(self._by_key.get(key)):
                return False
            if self._pending >= self.max_pending:
                self._rejected += 1
                return False
            self._by_key[key].append((func, args, kwargs, time.time()))
            self._pending += 1
            self._submitted += 1
            self._active_keys.add(key)
            self._ready.put(key)
            _r52_snap = (self._pending, self._active_workers, len(self._active_keys))
        if _r52_pool_key_interesting(key):
            r52_diag('POOL_SUBMIT_UNIQUE', pool=self.name, key=key, pending=_r52_snap[0], active=_r52_snap[1], keys=_r52_snap[2], func=getattr(func,'__name__',type(func).__name__))
        return True

    def key_status(self, key) -> dict:
        """Small introspection helper for UI status; no queue mutation."""
        key = str(key)
        with self._lock:
            q = self._by_key.get(key)
            return {'active': key in self._active_keys, 'queued': len(q) if q else 0}

    def _worker(self):
        while True:
            key = self._ready.get()
            task = None
            with self._lock:
                q = self._by_key.get(key)
                if q:
                    task = q.popleft()
                    self._active_workers += 1
                else:
                    self._active_keys.discard(key)
                    self._by_key.pop(key, None)
            if task is None:
                self._ready.task_done()
                continue
            func, args, kwargs, enqueued_at = task
            wait = max(0.0, time.time() - enqueued_at)
            with self._lock:
                self._max_wait = max(self._max_wait, wait)
                _r52_tid = threading.get_ident()
                self._running[_r52_tid] = {'key':key,'func':getattr(func,'__name__',type(func).__name__),'thread':threading.current_thread().name,'started_mono':time.monotonic(),'wait':wait}
            _r52_started = time.monotonic()
            if _r52_pool_key_interesting(key):
                r52_diag('POOL_WORKER_START', pool=self.name, key=key, wait=wait, func=getattr(func,'__name__',type(func).__name__), pending=self._pending, active=self._active_workers)
            try:
                func(*args, **kwargs)
                with self._lock:
                    self._completed += 1
            except Exception as exc:
                with self._lock:
                    self._failed += 1
                    self._last_error = str(exc)[:300]
                try:
                    log_error(f'POOL {self.name}: {exc}')
                except Exception:
                    logging.exception('POOL %s', self.name)
            finally:
                _r52_elapsed = max(0.0, time.monotonic() - _r52_started)
                with self._lock:
                    self._running.pop(threading.get_ident(), None)
                    self._pending = max(0, self._pending - 1)
                    self._active_workers = max(0, self._active_workers - 1)
                    q = self._by_key.get(key)
                    if q:
                        self._ready.put(key)
                    else:
                        self._by_key.pop(key, None)
                        self._active_keys.discard(key)
                    _r52_after = (self._pending, self._active_workers, len(self._active_keys))
                if _r52_pool_key_interesting(key):
                    r52_diag('POOL_WORKER_DONE', pool=self.name, key=key, elapsed=_r52_elapsed, pending=_r52_after[0], active=_r52_after[1], keys=_r52_after[2])
                task = func = args = kwargs = None
                self._ready.task_done()

    def wait_key_idle(self, key, timeout: float=15.0) -> bool:
        """Wait until all already-submitted tasks for one logical key finish.

        Used only by the durable MEGA witness before it declares a content update complete.
        It does not create new workers and does not affect unrelated chat keys.
        """
        key = str(key)
        deadline = time.monotonic() + max(0.0, float(timeout))
        while True:
            with self._lock:
                active = key in self._active_keys
                queued = bool(self._by_key.get(key))
            if not active and (not queued):
                return True
            if time.monotonic() >= deadline:
                return False
            time.sleep(0.02)

    def stats(self) -> dict:
        with self._lock:
            _now_m = time.monotonic()
            _running = [dict(row, age=round(max(0.0,_now_m-float(row.get('started_mono') or _now_m)),3)) for row in self._running.values()]
            return {'name': self.name, 'workers': self.workers, 'active': self._active_workers, 'pending': self._pending, 'keys': len(self._active_keys), 'submitted': self._submitted, 'completed': self._completed, 'failed': self._failed, 'rejected': self._rejected, 'max_wait': round(self._max_wait, 3), 'last_error': self._last_error, 'running': _running}


class LatestKeyedTaskPool:
    """R22 latest-wins keyed executor.

    At most one task per key is executing and at most one *latest* task is waiting.
    A newer render replaces an older queued render instead of building a stale UI
    backlog.  Network RTT therefore never occupies the callback worker lane.
    """

    def __init__(self, name: str, workers: int=6, max_pending_keys: int=256):
        self.name = str(name)
        self.workers = max(1, int(workers))
        self.max_pending_keys = max(10, int(max_pending_keys))
        self._ready = queue.Queue()
        self._lock = threading.RLock()
        self._latest = {}
        self._active_keys = set()
        self._seq = defaultdict(int)
        self._active_workers = 0
        self._submitted = 0
        self._replaced = 0
        self._completed = 0
        self._failed = 0
        self._rejected = 0
        self._max_wait = 0.0
        self._last_error = ''
        self._running = {}
        for idx in range(self.workers):
            threading.Thread(target=self._worker, name=f'{self.name}-{idx + 1}', daemon=True).start()

    def submit_latest(self, key, func, *args, **kwargs):
        key = str(key)
        with self._lock:
            if key not in self._active_keys and len(self._active_keys) >= self.max_pending_keys:
                self._rejected += 1
                return 0
            self._seq[key] += 1
            seq = int(self._seq[key])
            task = (seq, func, args, kwargs, time.monotonic())
            if key in self._latest:
                self._replaced += 1
            self._latest[key] = task
            self._submitted += 1
            if key not in self._active_keys:
                self._active_keys.add(key)
                self._ready.put(key)
            _r52_snap = (len(self._latest), self._active_workers, len(self._active_keys), self._replaced)
        r52_diag('LATEST_SUBMIT', pool=self.name, key=key, seq=seq, pending=_r52_snap[0], active=_r52_snap[1], keys=_r52_snap[2], replaced=_r52_snap[3], func=getattr(func,'__name__',type(func).__name__))
        return seq

    def is_latest(self, key, seq: int) -> bool:
        key = str(key)
        with self._lock:
            return int(self._seq.get(key, 0) or 0) == int(seq or 0)

    def _worker(self):
        while True:
            key = self._ready.get()
            task = None
            with self._lock:
                task = self._latest.pop(key, None)
                if task is not None:
                    self._active_workers += 1
            if task is None:
                with self._lock:
                    self._active_keys.discard(key)
                self._ready.task_done()
                continue
            seq, func, args, kwargs, enqueued_mono = task
            wait = max(0.0, time.monotonic() - enqueued_mono)
            with self._lock:
                self._max_wait = max(self._max_wait, wait)
                self._running[threading.get_ident()] = {'key':key,'seq':seq,'func':getattr(func,'__name__',type(func).__name__),'thread':threading.current_thread().name,'started_mono':time.monotonic(),'wait':wait}
            _r52_started = time.monotonic()
            r52_diag('LATEST_WORKER_START', pool=self.name, key=key, seq=seq, wait=wait, func=getattr(func,'__name__',type(func).__name__), pending=len(self._latest), active=self._active_workers, is_latest=int(self.is_latest(key,seq)))
            try:
                # If a newer render arrived before this task actually got CPU time,
                # discard this stale task without touching Telegram.
                if self.is_latest(key, seq):
                    func(*args, **kwargs)
                with self._lock:
                    self._completed += 1
            except Exception as exc:
                with self._lock:
                    self._failed += 1
                    self._last_error = str(exc)[:300]
                try:
                    log_error(f'POOL {self.name}: {exc}')
                except Exception:
                    logging.exception('POOL %s', self.name)
            finally:
                _r52_elapsed = max(0.0, time.monotonic() - _r52_started)
                with self._lock:
                    self._running.pop(threading.get_ident(), None)
                    self._active_workers = max(0, self._active_workers - 1)
                    if key in self._latest:
                        self._ready.put(key)
                    else:
                        self._active_keys.discard(key)
                    _r52_after=(len(self._latest),self._active_workers,len(self._active_keys))
                r52_diag('LATEST_WORKER_DONE', pool=self.name, key=key, seq=seq, elapsed=_r52_elapsed, pending=_r52_after[0], active=_r52_after[1], keys=_r52_after[2])
                task = func = args = kwargs = None
                self._ready.task_done()

    def stats(self) -> dict:
        with self._lock:
            _now_m=time.monotonic()
            _running=[dict(row, age=round(max(0.0,_now_m-float(row.get('started_mono') or _now_m)),3)) for row in self._running.values()]
            return {
                'name': self.name, 'workers': self.workers, 'active': self._active_workers,
                'pending': len(self._latest), 'keys': len(self._active_keys),
                'submitted': self._submitted, 'replaced': self._replaced,
                'completed': self._completed, 'failed': self._failed,
                'rejected': self._rejected, 'max_wait': round(self._max_wait, 3),
                'last_error': self._last_error, 'running': _running,
            }

class DelayedTaskScheduler:
    """Один поток хранит все логические таймеры без сотен threading.Timer."""

    def __init__(self, executor_pool: KeyedTaskPool):
        self.executor_pool = executor_pool
        self._cv = threading.Condition(threading.RLock())
        self._heap = []
        self._versions = {}
        self._deadlines = {}
        self._seq = 0
        self._submitted = 0
        self._executed = 0
        self._cancelled = 0
        self._failed_dispatch = 0
        # R45 stuck-fix: retry bookkeeping is per logical timer key.  A saturated
        # executor must not turn one pending timer into a 2 Hz error/log storm.
        self._retry_counts = {}
        self._last_retry_log = {}
        self._busy_requeues = 0
        threading.Thread(target=self._worker, name=f'{self.executor_pool.name}-scheduler', daemon=True).start()

    def _compact_locked(self, force: bool=False):
        live = len(self._deadlines)
        threshold = max(128, live * 4 + 64)
        if not force and len(self._heap) <= threshold:
            return 0
        before = len(self._heap)
        self._heap = [item for item in self._heap if int(self._versions.get(item[2], 0)) == int(item[3]) and self._deadlines.get(item[2]) == item[0]]
        heapq.heapify(self._heap)
        return max(0, before - len(self._heap))

    def compact(self) -> int:
        with self._cv:
            return self._compact_locked(True)

    def schedule(self, key, delay: float, func, *args, **kwargs):
        key = str(key)
        run_at = time.time() + max(0.0, float(delay or 0))
        with self._cv:
            self._seq += 1
            version = int(self._versions.get(key, 0)) + 1
            self._versions[key] = version
            self._deadlines[key] = run_at
            heapq.heappush(self._heap, (run_at, self._seq, key, version, func, args, kwargs))
            self._submitted += 1
            self._compact_locked(False)
            self._cv.notify_all()
        return run_at

    def cancel(self, key):
        key = str(key)
        with self._cv:
            self._versions[key] = int(self._versions.get(key, 0)) + 1
            if key in self._deadlines:
                self._deadlines.pop(key, None)
                self._cancelled += 1
            self._cv.notify_all()

    def deadline(self, key):
        with self._cv:
            return self._deadlines.get(str(key))

    def stats(self):
        with self._cv:
            return {
                'scheduled': len(self._deadlines), 'heap': len(self._heap),
                'submitted': self._submitted, 'executed': self._executed,
                'cancelled': self._cancelled, 'dispatch_failed': self._failed_dispatch,
                'busy_requeues': self._busy_requeues,
                'retry_keys': len(self._retry_counts),
            }

    def _worker(self):
        while True:
            with self._cv:
                while not self._heap:
                    self._cv.wait()
                run_at, seq, key, version, func, args, kwargs = self._heap[0]
                wait = run_at - time.time()
                if wait > 0:
                    self._cv.wait(timeout=wait)
                    continue
                heapq.heappop(self._heap)
                if int(self._versions.get(key, 0)) != int(version):
                    continue
                self._deadlines.pop(key, None)

            # One stable executor key per logical timer.  schedule() is already latest-wins
            # for a key, so allowing multiple concurrent executor copies is both wasteful
            # and a source of queue amplification.
            dispatch_key = f'delay:{key}'
            try:
                status = self.executor_pool.key_status(dispatch_key)
            except Exception:
                status = {'active': False, 'queued': 0}
            same_key_busy = bool(status.get('active') or status.get('queued'))
            ok = False if same_key_busy else self.executor_pool.submit_unique(dispatch_key, self._execute, func, args, kwargs)
            if ok:
                with self._cv:
                    self._retry_counts.pop(key, None)
                    self._last_retry_log.pop(key, None)
                continue

            now = time.time()
            with self._cv:
                if same_key_busy:
                    self._busy_requeues += 1
                    retry_count = int(self._retry_counts.get(key, 0) or 0)
                    retry_delay = 0.35
                else:
                    self._failed_dispatch += 1
                    retry_count = int(self._retry_counts.get(key, 0) or 0) + 1
                    self._retry_counts[key] = retry_count
                    # 0.5, 1, 2, 4, 8, 10s (+ tiny deterministic jitter).
                    retry_delay = min(10.0, 0.5 * (2 ** min(max(0, retry_count - 1), 5)))
                    retry_delay += 0.05 * ((self._seq + retry_count) % 5)
                if int(self._versions.get(key, 0)) == int(version):
                    retry_at = now + retry_delay
                    self._seq += 1
                    self._deadlines[key] = retry_at
                    heapq.heappush(self._heap, (retry_at, self._seq, key, version, func, args, kwargs))
                    self._cv.notify_all()

            # Same-key busy is normal coalescing, not an error.  Real capacity failures
            # are throttled to at most one log line per key every 5 seconds.
            if not same_key_busy:
                should_log = False
                with self._cv:
                    last_log = float(self._last_retry_log.get(key, 0.0) or 0.0)
                    if now - last_log >= 5.0:
                        self._last_retry_log[key] = now
                        should_log = True
                if should_log:
                    try:
                        log_error(f'DELAYED QUEUE FULL, BACKOFF: {key} retry={retry_count} next={retry_delay:.2f}s')
                    except Exception:
                        pass

    def _execute(self, func, args, kwargs):
        try:
            func(*args, **kwargs)
        finally:
            with self._cv:
                self._executed += 1

def _env_int(name: str, default: int, minimum: int=1, maximum: int=128) -> int:
    try:
        return max(minimum, min(maximum, int(os.getenv(name, str(default)) or default)))
    except Exception:
        return int(default)
WEBHOOK_TASK_POOL = KeyedTaskPool('content', _env_int('WEBHOOK_WORKERS', 2, 2, 8), _env_int('WEBHOOK_MAX_PENDING', 400, 50, 2000))
